    fn get_contact_relative_position(&mut self, ctx: &mut NativeCtx<'_>, range: f32, angle: f32) -> i32 { 0 }

    /// Script function `settarget`.
    ///
    /// Parameters: `attacker_id`: integer, `target_id`: integer.
