    /// Parameters: `weapon_index`: integer.
    /// Returns: integer.
    fn get_weapon_shots(&mut self, ctx: &mut NativeCtx<'_>, weapon_index: i32) -> i32 { 0 }

    /// Script function `getweaponranges`.
    ///
    /// Parameters: `object_id`: integer, `range_list`: real array.
    /// Returns: nothing.
    ///
    /// Original description (C++ comment):
    /// > GET WEAPON RANGES function:
    /// > Returns the range in meters for the object's shortest,
