    fn get_weapon_ranges(&mut self, ctx: &mut NativeCtx<'_>, object_id: i32, range_list: ArrayRef) {}

    /// Script function `getobjectposition`.
    ///
    /// Parameters: `object_id`: integer, `coord_list`: real array.
