    fn get_object_position(&mut self, ctx: &mut NativeCtx<'_>, object_id: i32, coord_list: ArrayRef) {}

    /// Script function `getintegermemory`.
    ///
    /// Parameters: `mem_index`: integer.
    /// Returns: integer.
    ///
    /// Original description (C++ comment):
    /// > GET MEMORY INTEGER function:
    /// > Returns current integer value in memory cell of pilot.
    /// > PARAMS: integer
    /// > RETURN: integer
    fn get_integer_memory(&mut self, ctx: &mut NativeCtx<'_>, mem_index: i32) -> i32 { 0 }

    /// Script function `getrealmemory`.
    ///
    /// Parameters: `mem_index`: integer.
    /// Returns: real.
    ///
    /// Original description (C++ comment):
    /// > GET MEMORY REAL function:
    /// > Returns current real value in memory cell of pilot.
    /// > PARAMS: integer
    /// > RETURN: real
    fn get_real_memory(&mut self, ctx: &mut NativeCtx<'_>, mem_index: i32) -> f32 { 0.0 }

    /// Script function `getalarmtriggers`.
    ///
    /// Parameters: `trigger_list`: integer array.
    /// Returns: integer.
    ///
    /// Original description (C++ comment):
    /// > GET ALARM TRIGGERS function:
    /// > Returns number of triggers for the current combat event handler.
